def fibfib(n: int) -> int:
    if n < 0:
        return -1  # This line is just a placeholder, handle negative numbers.

    # Base cases
    if n == 0:
        return 0
    if n == 1 or n == 2:
        return 1

    fibfib_cache = [0] * (n + 1)
    fibfib_cache[1] = 1
    fibfib_cache[2] = 1
    for i in range(3, n + 1):
        fibfib_cache[i] = fibfib_cache[i - 1] + fibfib_cache[i - 2] + fibfib_cache[i - 3]

    return fibfib_cache[n]
