                if ele == 1:
                    buckets[i, j] += 1
            buckets[i] += (grid[i] == 1) * 2  # alternate water units in row
        else:
            for j in range(1, 1 + sum(row)):
                buckets[i, j] += buckets[i, j-1]
            buckets[i][0] += 1  # count the leftmost 1 to full bucket

    # Process columns
    for j in range(1, n + 1):
        buckets[0, j] += buckets[0, j-1]
        for i in range(1, m + 1):
            buckets[i, j] += buckets[i, j-1]

    # Find the maximum number of filled buckets
    result = 0
    for bucket in buckets:
        for num in bucket:
            result += num

